<?php
/** Generic taxonomy page; specific object/library/person templates take precedence. */
if (!defined('ABSPATH')) exit;
get_header();
$term = get_queried_object();
$lead = $term instanceof WP_Term ? interworld_content_value('iw_page_lead', $term->taxonomy . '_' . $term->term_id) : '';
?>
<main class="iw-editorial-page iw-editorial-archive">
  <header class="iw-editorial-archive-header"><nav class="iw-editorial-breadcrumbs" aria-label="Хлебные крошки"><a href="<?php echo esc_url(home_url('/')); ?>">Главная</a><span aria-hidden="true">›</span><span><?php echo esc_html($term instanceof WP_Term ? $term->name : 'Раздел'); ?></span></nav><div class="iw-editorial-eyebrow">ТЕМА МЕЖМИРЬЯ</div><h1><?php echo esc_html($term instanceof WP_Term ? $term->name : 'Раздел'); ?></h1><?php if ($lead) : ?><p class="iw-editorial-lead"><?php echo esc_html($lead); ?></p><?php elseif ($term instanceof WP_Term && $term->description) : ?><div class="iw-editorial-lead"><?php echo wp_kses_post(wpautop($term->description)); ?></div><?php else : ?><p class="iw-editorial-lead">Описание будет добавлено после проверки материалов раздела.</p><?php endif; ?></header>
  <?php if ($term instanceof WP_Term && trim((string)$term->description) !== '') : ?><section class="iw-editorial-body"><?php echo wp_kses_post(wpautop($term->description)); ?></section><?php endif; ?>
  <section class="iw-editorial-catalog"><form class="iw-catalog-tools" method="get"><label><span class="screen-reader-text">Поиск в разделе</span><input type="search" name="iw_q" value="<?php echo esc_attr(isset($_GET['iw_q']) ? sanitize_text_field(wp_unslash($_GET['iw_q'])) : ''); ?>" placeholder="Найти материал"></label><label><span class="screen-reader-text">Сортировка</span><select name="iw_sort"><option value="alphabetical">По алфавиту</option><option value="newest" <?php selected(isset($_GET['iw_sort']) ? sanitize_key(wp_unslash($_GET['iw_sort'])) : '', 'newest'); ?>>Сначала новые</option></select></label><button type="submit">Найти</button></form>
    <?php if (have_posts()) : ?><div class="iw-editorial-grid"><?php while (have_posts()) : the_post(); $id=get_the_ID(); $excerpt=get_the_excerpt(); if (!$excerpt) $excerpt=interworld_content_value('iw_lead',$id); ?><article class="iw-editorial-card"><a class="iw-editorial-card-image" href="<?php the_permalink(); ?>"><?php if (has_post_thumbnail()) the_post_thumbnail('medium_large',array('loading'=>'lazy','alt'=>'')); else : ?><span aria-hidden="true">INTERWORLD</span><?php endif; ?></a><div class="iw-editorial-card-copy"><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><?php if ($excerpt) : ?><p><?php echo esc_html(wp_trim_words(wp_strip_all_tags($excerpt), 24)); ?></p><?php endif; ?><a class="iw-editorial-more" href="<?php the_permalink(); ?>">Подробнее →</a></div></article><?php endwhile; ?></div><nav class="iw-editorial-pagination" aria-label="Страницы списка"><?php echo interworld_content_pagination(max(1,(int)get_query_var('paged')),$wp_query->max_num_pages,'list'); ?></nav><?php else : ?><div class="iw-editorial-empty"><h2>Записей пока нет</h2><p>Раздел будет заполнен после подготовки проверенных материалов.</p></div><?php endif; ?>
  </section>
</main>
<?php get_footer(); ?>
